        </form>
    </section>

    <div class="pagination">
        {% if page > 1 %}
          <a href="?page={{ page - 1 }}">← Prev</a>
        {% endif %}
        <span class="active">Page {{ page }}</span>
        {% if has_next %}
          <a href="?page={{ page + 1 }}">Next →</a>
        {% endif %}
    </div>
</body>
</html>
'''

# --- Routes ---

@app.route('/messages', methods=['GET', 'POST'])
def messages():
    db = get_db()

    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        content = request.form.get('content', '').strip()

        if not username or not content:
            flash('Username and content are required.', 'error')
            return redirect(request.url)

        created_at = datetime.now(timezone.utc).isoformat()
        db.execute(
            'INSERT INTO messages (username, content, created_at) VALUES (?, ?, ?)',
            (username, content, created_at)
        )
        db.commit()
        flash('Message posted successfully!', 'success')
        return redirect(url_for('messages'))

    # GET handling with pagination and sorting
    limit = int(request.args.get('limit', 10))
    offset = int(request.args.get('offset', 0))
    sort = request.args.get('sort', 'desc').upper()

    # Validate sort
    if sort not in ('ASC', 'DESC'):
        sort = 'DESC'

    # Get total count for pagination
    total_row = db.execute('SELECT COUNT(*) FROM messages').fetchone()
    total = total_row['COUNT(*)']

    # Calculate pagination
    total_pages = max(1, (total + limit - 1) // limit)
    page = max(1, min(int(request.args.get('page', 1)), total_pages))
    offset = (page - 1) * limit

    # Fetch messages with sorting
    sort_clause = 'ASC' if sort == 'ASC' else 'DESC'
    rows = db.execute(
        f'SELECT id, username, content, created_at FROM messages ORDER BY created_at {sort_clause} LIMIT ? OFFSET ?',
        (limit, offset)
    ).fetchall()

    # Format messages for template
    formatted_messages = []
    for row in rows:
        # Parse the ISO datetime and format nicely
        try:
            dt = datetime.fromisoformat(row['created_at'])
            formatted_time = dt.strftime('%b %d, %Y %H:%M')
        except (ValueError, TypeError):
            formatted_time = row['created_at']

        formatted_messages.append({
            'username': row['username'],
            'content': row['content'],
            'created_at': formatted_time
        })

    has_next = page < total_pages

    return render_template_string(BASE_HTML, messages=formatted_messages, page=page, has_next=has_next)


